<div class="page-header"><div><span class="eyebrow">A FRIENDLY LITTLE NUDGE</span><h1>A little news from your learning space.</h1><p>Your reminders, feedback and well-earned moments.</p></div><?php if($notifications): ?><div class="page-actions"><button class="btn btn-secondary btn-small" data-api-button="<?= e(route_url('/api/notifications/read')) ?>">Mark all as read <?= icon('check',15) ?></button></div><?php endif; ?></div><section class="card table-card"><?php if($notifications): ?><?php foreach($notifications as $n): ?><article class="notification-row <?= !$n['read_at']?'unread':'' ?>"><span class="icon-tile <?= $n['kind']==='milestones'?'orange':'blue' ?>"><?= icon(match($n['kind']){'milestones'=>'award','feedback'=>'message','study'=>'calendar','streak'=>'flame','weekly'=>'chart',default=>'bell'},20) ?></span><div><h3><a href="<?= e(route_url(($n['link']))) ?>"><?= e($n['title']) ?></a></h3><p><?= e($n['body']) ?></p><small><?= niceDate($n['created_at'],'M j, Y · H:i') ?> UTC<?= !$n['read_at']?' · Unread':'' ?></small></div><a href="<?= e(route_url(($n['link']))) ?>" class="icon-button" aria-label="Open <?= e($n['title']) ?>"><?= icon('arrow-up-right',17) ?></a></article><?php endforeach; ?><?php pagination($total); ?><?php else: emptyState('bell','A little quiet is a good thing.','Your feedback, reminders and milestone notifications will appear here when there’s something useful to share.','/settings#notification-preferences','Choose my notifications');endif; ?></section>
